Import Library    RequestsLibrary
Create Session    booker    https://restful-booker.herokuapp.com
${auth}=    POST On Session    booker    /auth    json={"username": "admin", "password": "password123"}    expected_status=200
Log    ${auth.json()}
${bad}=    POST On Session    booker    /auth    json={"username": "admin", "password": "wrong"}    expected_status=any
Log    ${bad.status_code} ${bad.text}
${resp}=    POST On Session    booker    /booking    json={"firstname": "ProbeX", "lastname": "Tester", "totalprice": 245, "depositpaid": true, "bookingdates": {"checkin": "2026-12-01", "checkout": "2026-12-05"}, "additionalneeds": "Breakfast"}    expected_status=any
Log    ${resp.status_code} ${resp.text}

&{creds}=    Create Dictionary    username=admin    password=password123
${auth}=    POST On Session    booker    /auth    json=${creds}    expected_status=200
