&{badcreds}=    Create Dictionary    username=admin    password=wrong
${bad}=    POST On Session    booker    /auth    json=${badcreds}    expected_status=any
Log    ${bad.status_code} ${bad.text}
&{bookdates}=    Create Dictionary    checkin=2026-12-01    checkout=2026-12-05
&{payload}=    Create Dictionary    firstname=ProbeX    lastname=Tester    totalprice=${245}    depositpaid=${True}    bookingdates=${bookdates}    additionalneeds=Breakfast
${resp}=    POST On Session    booker    /booking    json=${payload}    expected_status=any
Log    ${resp.status_code} ${resp.text}

&{patch}=    Create Dictionary    firstname=ProbeY
${nt}=    PATCH On Session    booker    /booking/647    json=${patch}    expected_status=any
Log    NOTOKEN ${nt.status_code} ${nt.text}
&{cookie}=    Create Dictionary    Cookie=token=d124e9754f8a664    Accept=application/json
${wt}=    PATCH On Session    booker    /booking/647    json=${patch}    headers=${cookie}    expected_status=any
Log    TOKEN ${wt.status_code} ${wt.text}
${srch}=    GET On Session    booker    /booking    params=firstname=ProbeY&lastname=Tester    expected_status=any
Log    SEARCH ${srch.status_code} ${srch.text}
${srch2}=    GET On Session    booker    /booking    params=firstname=ProbeX&lastname=Tester    expected_status=any
Log    SEARCH2 ${srch2.status_code} ${srch2.text}
&{bookdates}=    Create Dictionary    checkin=2027-01-10    checkout=2027-01-12
